package edu.pe.cibertec.saibm.inventario;
import static org.assertj.core.api.Assertions.assertThat; import java.nio.file.*; import org.junit.jupiter.api.Test;
class InfrastructureContractTest { @Test void boundaryAndRuntimeContractsAreExplicit() throws Exception {var root=Path.of("src/main");try(var fs=Files.walk(root.resolve("java/edu/pe/cibertec/saibm/inventario/domain"))){fs.filter(p->p.toString().endsWith(".java")).forEach(p->{try{assertThat(Files.readString(p)).doesNotContain("org.springframework","jakarta.persistence");}catch(Exception e){throw new RuntimeException(e);}});}var app=Files.readString(root.resolve("java/edu/pe/cibertec/saibm/inventario/application/port/in/InventoryUseCase.java"));assertThat(app).doesNotContain("port.out");var sql=Files.readString(root.resolve("resources/db/migration/V1__inventario.sql"));assertThat(sql).contains("inventory_stock","inventory_holds","inventory_movements","inventory_outbox","inventory_inbox").doesNotContain("references");var y=Files.readString(root.resolve("resources/application.yml"));assertThat(y).contains("name: inventario-service","ddl-auto: validate","rabbitmq:","probes:");var rabbit=Files.readString(root.resolve("java/edu/pe/cibertec/saibm/inventario/infrastructure/messaging/RabbitConfig.java"));assertThat(rabbit).contains("InventoryHoldRequested.v1","InventoryReleaseRequested.v1","inventory-dlq");var publisher=Files.readString(root.resolve("java/edu/pe/cibertec/saibm/inventario/infrastructure/messaging/OutboxPublisher.java"));assertThat(publisher).contains("publisher-enabled","havingValue = \"true\"").doesNotContain("markPublished()","outbox.save(");}}
